```js
import {
  Group, Mesh, BoxGeometry, OctahedronGeometry, PlaneGeometry,
  Color, AmbientLight, DirectionalLight, PointLight,
  MeshStandardNodeMaterial, MeshBasicNodeMaterial
} from 'three/webgpu';
import { uv, mix, smoothstep, float, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const root = new Group();
  const content = new Group();
  root.add(content);

  const colors = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d', paper: '#e8ecf2', accent: '#ff2a38', surface: '#0b0b10'
  };
  const ink = new Color(colors.ink);
  const paper = new Color(colors.paper);
  const accent = new Color(colors.accent);
  const surface = new Color(colors.surface);

  // ---- backdrop: engineered dark gradient (stage, never void) ----
  const bgGeo = new PlaneGeometry(7.2, 6.2);
  const bgMat = new MeshBasicNodeMaterial({ toneMapped: false });
  bgMat.colorNode = mix(
    uniform(surface),
    uniform(ink),
    smoothstep(float(0.0), float(1.0), uv().y)
  );
  bgMat.side = 2;
  const bg = new Mesh(bgGeo, bgMat);
  bg.position.set(0, 0, -2.5);
  content.add(bg);

  // subtle vignette accent ring far behind jewel
  const ringGeo = new PlaneGeometry(1.6, 1.6);
  const ringMat = new MeshBasicNodeMaterial({
    transparent: true, opacity: 0.12, toneMapped: false
  });
  ringMat.color = accent;
  const ring = new Mesh(ringGeo, ringMat);
  ring.position.set(0, 0, -2.2);
  content.add(ring);

  // ---- machined rule ----
  const ruleMat = new MeshStandardNodeMaterial();
  ruleMat.color = paper;
  ruleMat.metalness = 0.55;
  ruleMat.roughness = 0.5;
  ruleMat.clearcoat = 0.25;

  const ruleGeo = new BoxGeometry(2.4, 0.05, 0.05);
  const rule = new Mesh(ruleGeo, ruleMat);
  content.add(rule);

  // beveled machined end caps
  const mkCap = (x) => {
    const g = new OctahedronGeometry(0.06, 0);
    const c = new Mesh(g, ruleMat);
    c.position.set(x, 0, 0);
    c.rotation.z = Math.PI / 4;
    content.add(c);
    return c;
  };
  mkCap(-1.2); mkCap(1.2);

  // secondary thin track beneath for machined depth read
  const trackMat = new MeshStandardNodeMaterial();
  trackMat.color = paper;
  trackMat.metalness = 0.4;
  trackMat.roughness = 0.6;
  const trackGeo = new BoxGeometry(2.0, 0.012, 0.03);
  const track = new Mesh(trackGeo, trackMat);
  track.position.set(0, -0.05, -0.02);
  content.add(track);

  // ---- center jewel ----
  const jewelMat = new MeshStandardNodeMaterial();
  jewelMat.color = accent;
  jewelMat.emissive = accent;
  jewelMat.emissiveIntensity = 1.6;
  jewelMat.metalness = 0.9;
  jewelMat.roughness = 0.15;
  const jewelGeo = new OctahedronGeometry(0.1, 0);
  const jewel = new Mesh(jewelGeo, jewelMat);
  jewel.rotation.set(Math.PI / 6, Math.PI / 4, 0);
  content.add(jewel);

  // jewel halo (small, accent, behind)
  const haloGeo = new PlaneGeometry(0.5, 0.5);
  const haloMat = new MeshBasicNodeMaterial({
    transparent: true, opacity: 0.22, toneMapped: false
  });
  haloMat.color = accent;
  const halo = new Mesh(haloGeo, haloMat);
  halo.position.set(0, 0, -0.08);
  content.add(halo);

  // ---- lights (product-shot grade) ----
  const amb = new AmbientLight(0xffffff, 0.6);
  content.add(amb);

  const key = new DirectionalLight(0xffffff, 1.15);
  key.position.set(3, 3.5, 4);
  content.add(key);

  const rim = new DirectionalLight(0xffffff, 0.7);
  rim.position.set(-3, -1.5, -2);
  content.add(rim);

  const accentPt = new PointLight(accent.getHex(), 0.9, 2.5, 2);
  accentPt.position.set(0, 0, 0.35);
  content.add(accentPt);

  // ---- async GLB load (cta-hero mesh, repurposed as subtle base panel) ----
  let loadedGlb = null;
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      const glbRoot = gltf.scene ?? gltf;
      glbRoot.traverse((o) => {
        if (o.isMesh) {
          o.castShadow = true;
          o.receiveShadow = true;
          if (o.material && o.material.roughness !== undefined) {
            o.material.roughness = Math.min(o.material.roughness ?? 0.5, 0.6);
            o.material.metalness = Math.min(o.material.metalness ?? 0.4, 0.55);
          }
        }
      });
      glbRoot.position.set(0, -0.45, -0.35);
      glbRoot.scale.setScalar(0.32);
      content.add(glbRoot);
      loadedGlb = glbRoot;
    }).catch(() => { /* resource may be optional in mock runtime */ });
  }

  // ---- motion ----
  const idleTl = gsap.timeline({ repeat: -1, yoyo: true });
  idleTl.to(jewelMat, {
    emissiveIntensity: 2.1, duration: 2.4, ease: 'sine.inOut'
  });
  idleTl.to(jewel.scale, {
    x: 1.06, y: 1.06, z: 1.06, duration: 2.4, ease: 'sine.inOut'
  }, 0);

  const spinTl = gsap.to(jewel.rotation, {
    y: jewel.rotation.y + Math.PI * 2,
    duration: 14, ease: 'none', repeat: -1
  });

  // entry: rise-in (subtle), weighted-settle
  content.position.y = 0.35;
  content.scale.set(0.97, 0.97, 0.97);
  const entryTl = gsap.timeline();
  entryTl.to(content.position, {
    y: 0, duration: 0.7, ease: 'power3.out'
  });
  entryTl.to(content.scale, {
    x: 1.04, y: 1.04, z: 1.04, duration: 0.7, ease: 'power3.out'
  }, 0);
  entryTl.to(content.scale, {
    x: 1.0, y: 1.0, z: 1.0, duration: 0.9, ease: 'power4.out'
  }, 0.55);

  const allTls = [idleTl, spinTl, entryTl];

  // ---- interactions ----
  const handlers = {
    hoverIn: () => {
      gsap.to(content.position, {
        y: 0.15, duration: 0.4, ease: 'power3.out', overwrite: 'auto'
      });
      gsap.to(haloMat, {
        opacity: 0.4, duration: 0.4, ease: 'power2.out'
      });
    },
    hoverOut: () => {
      gsap.to(content.position, {
        y: 0, duration: 0.4, ease: 'power3.out', overwrite: 'auto'
      });
      gsap.to(haloMat, {
        opacity: 0.22, duration: 0.4, ease: 'power2.out'
      });
    },
    click: () => {
      const press = gsap.timeline();
      press.to(content.scale, {
        x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out'
      });
      press.to(content.scale, {
        x: 1.0, y: 1.0, z: 1.0, duration: 0.18, ease: 'power2.out'
      });
      allTls.push(press);
      ctx.emit('hub-home.select', { node: config.id ?? 'ornamental-divider' });
    }
  };
  root.userData.handlers = handlers;

  // ---- cleanup ----
  root.userData.cleanup = () => {
    for (const t of allTls) {
      try { t.kill(); } catch (_) {}
    }
    allTls.length = 0;
    [bgGeo, ringGeo, ruleGeo, trackGeo, jewelGeo, haloGeo].forEach((g) => g.dispose());
    [bgMat, ringMat, ruleMat, trackMat, jewelMat, haloMat].forEach((m) => {
      try { m.dispose(); } catch (_) {}
    });
    if (loadedGlb) {
      loadedGlb.traverse((o) => {
        if (o.isMesh) {
          o.geometry?.dispose?.();
          o.material?.dispose?.();
        }
      });
      content.remove(loadedGlb);
      loadedGlb = null;
    }
  };

  return root;
}
